<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'
import { ApiError,describeError,downloadFile,formatDate,request,workspacePath,type Workspace } from './api'
import { scenarioContextHref } from './scenario-context'
import { dataCaseAIPreview,dataChannelLabels,dataEnforcementLabels,dataEndpointScopeLabels,dataEndpointStageLabels,type DataCase,type DataScope,type DataWindow } from './data-security'
import EndpointChannelsPanel from './EndpointChannelsPanel.vue'
import type { EndpointEventScope } from './endpoint-channels'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const base=workspacePath(props.workspace.slug),active=new AbortController(),editor=computed(()=>['owner','operator'].includes(props.workspace.role))
const sources=ref<{id:number;name:string;kind:string;revokedAt?:string}[]>([]),profiles=ref<{id:number;name:string;model:string;enabled:boolean;allowMetadata:boolean}[]>([])
const aiMode=ref('local')
const endpointChannelsOpen=ref(false)
const eventsPanel=ref<HTMLElement>()
const sourceId=ref(0),subjectRef=ref(''),deviceRef=ref(''),channel=ref(''),from=ref(local(new Date(Date.now()-86400000))),to=ref(local(new Date())),title=ref(''),windowData=ref<DataWindow>(),cases=ref<DataCase[]>([]),selected=ref<DataCase>(),busy=ref(false),error=ref(''),notice=ref(''),feedback=ref('needs_investigation'),note=ref(''),profileId=ref(0),consent=ref(false)
function local(d:Date){return new Date(d.getTime()+8*3600000).toISOString().slice(0,16)}
function scope():DataScope{return {sourceId:Number(sourceId.value),subjectRef:subjectRef.value.trim()||undefined,deviceRef:deviceRef.value.trim()||undefined,channel:channel.value||undefined,from:new Date(from.value+':00+08:00').toISOString(),to:new Date(to.value+':00+08:00').toISOString()}}
function failure(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return};error.value=describeError(e)}
async function load(){try{const [a,b,c]=await Promise.all([request<{items:typeof sources.value}>(base+'/operations/sources',{signal:active.signal}),request<{items:DataCase[]}>(base+'/data-security/cases',{signal:active.signal}),request<{profiles:typeof profiles.value;settings:{mode:string}}>(base+'/classification/engine',{signal:active.signal})]);sources.value=a.items.filter(v=>v.kind==='security_events'&&!v.revokedAt);cases.value=b.items;profiles.value=c.profiles.filter(v=>v.enabled&&v.allowMetadata);aiMode.value=c.settings.mode}catch(e){failure(e)}}
async function query(){if(busy.value)return;busy.value=true;error.value='';try{const q=new URLSearchParams();for(const [key,value] of Object.entries(scope()))if(value!==undefined)q.set(key,String(value));windowData.value=await request<DataWindow>(base+'/data-security/events?'+q,{signal:active.signal})}catch(e){failure(e)}finally{busy.value=false}}
async function inspectEndpointEvents(value:EndpointEventScope){if(busy.value){error.value='当前操作尚未结束，请稍后核对此设备事件。';return};windowData.value=undefined;sourceId.value=value.sourceId;deviceRef.value=value.deviceRef;subjectRef.value='';channel.value=value.channel||'';await query();await nextTick();eventsPanel.value?.scrollIntoView({block:'start'})}
async function freeze(){if(busy.value||!editor.value||!title.value.trim())return;busy.value=true;error.value='';try{selected.value=await request<DataCase>(base+'/data-security/cases',{method:'POST',body:JSON.stringify({title:title.value.trim(),scope:scope()}),signal:active.signal});consent.value=false;await load();notice.value='已冻结同范围的来源事件、关联关系和覆盖缺口。'}catch(e){failure(e)}finally{busy.value=false}}
async function choose(id:number){if(busy.value)return;busy.value=true;error.value='';try{selected.value=await request<DataCase>(base+'/data-security/cases/'+id,{signal:active.signal});consent.value=false;note.value='';notice.value=''}catch(e){failure(e)}finally{busy.value=false}}
async function addFeedback(){if(!selected.value||!note.value.trim()||busy.value)return;busy.value=true;error.value='';try{await request(base+'/data-security/cases/'+selected.value.id+'/feedback',{method:'POST',body:JSON.stringify({decision:feedback.value,note:note.value.trim()}),signal:active.signal});selected.value=await request<DataCase>(base+'/data-security/cases/'+selected.value.id,{signal:active.signal});note.value='';notice.value='已保存人工反馈，未改写原始事件或自动关闭监管检查。'}catch(e){failure(e)}finally{busy.value=false}}
async function assess(){if(!selected.value||!consent.value||!profileId.value||busy.value)return;busy.value=true;error.value='';try{await request(base+'/data-security/cases/'+selected.value.id+'/ai-reference',{method:'POST',body:JSON.stringify({profileId:Number(profileId.value),allowMetadata:true,caseDigest:selected.value.snapshotDigest}),signal:active.signal});selected.value=await request<DataCase>(base+'/data-security/cases/'+selected.value.id,{signal:active.signal});consent.value=false;notice.value='模型参考已留存。请核对其引用的事件及不确定性，再决定如何处理。'}catch(e){failure(e)}finally{busy.value=false}}
async function exportCase(format:'html'|'json'){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await downloadFile(base+'/data-security/cases/'+selected.value.id+'/export?format='+format,`data-security-case-${selected.value.id}.${format}`,active.signal)}catch(e){failure(e)}finally{busy.value=false}}
function feedbackText(s:Record<string,unknown>){if(typeof s.note==='string')return s.note;const r=s.result;if(r&&typeof r==='object'&&'summary'in r&&typeof r.summary==='string')return r.summary;return '查看保存的参考记录'}
onMounted(()=>{void load()});onBeforeUnmount(()=>active.abort())
</script>
<template><section class="data-security-panel"><header><h2>数据外发与事件调查</h2><p>按来源核对终端、数据库与 AI 使用事件，将关联证据冻结成调查快照。敏感正文、SQL、提示词和真实身份留在源端。</p><a class="table-link" :href="scenarioContextHref(workspace.slug,'operations')">登记或管理安全事件来源</a></header>
<p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message message-success" role="status">{{notice}}</p>
<section class="panel"><div class="panel-heading"><div><h3>USB、打印与剪贴板</h3><p>核对已接入设备的真实能力，再登记通道策略、独立审批和源端回执。</p></div><button class="button" type="button" :aria-expanded="endpointChannelsOpen" aria-controls="endpoint-channels" @click="endpointChannelsOpen=!endpointChannelsOpen">{{endpointChannelsOpen?'收起设备与策略':'查看设备与通道策略'}}</button></div></section>
<EndpointChannelsPanel v-if="endpointChannelsOpen" id="endpoint-channels" :workspace="workspace" @session-expired="emit('sessionExpired')" @inspect-events="inspectEndpointEvents" />
<details class="panel source-guide"><summary>接入与覆盖范围</summary><p>现有事件桥接支持受授权的规范化 DLP 投影、Wazuh 文件变更和 PostgreSQL pgAudit 日志。原有未携带数据上下文的告警不会被补造成终端事件。</p><p>源端策略 SDK 可检查指定通道、保护类别和批准的 AI 域名；受控文本复制工具会实际拒绝被策略阻止的复制。USB、打印、剪贴板等通道须由对应终端工具提供真实事件和执行证据，此页面不会自行取得这些通道的系统权限。</p><p>调查只关联同一来源内相同主体或设备引用。来源声称阻断、实际执行、自动复测和独立复核分别核验。</p></details>
<form class="panel data-filter" @submit.prevent="query"><label>安全事件来源<select v-model.number="sourceId" :disabled="busy"><option :value="0">工作区全部已接入来源</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.name}} · #{{s.id}}</option></select></label><label>数据通道<select v-model="channel" :disabled="busy"><option value="">全部已记录通道</option><option v-for="(label,key) in dataChannelLabels" :key="key" :value="key">{{label}}</option></select></label><label>主体引用（可选）<input v-model="subjectRef" pattern="[0-9a-f]{64}" placeholder="客户侧 HMAC 引用，不填写姓名或账号" :disabled="busy"></label><label>设备引用（可选）<input v-model="deviceRef" pattern="[0-9a-f]{64}" placeholder="客户侧 HMAC 引用" :disabled="busy"></label><label>开始时间（上海）<input v-model="from" type="datetime-local" required :disabled="busy"></label><label>结束时间（上海）<input v-model="to" type="datetime-local" required :disabled="busy"></label><div class="actions"><button class="button button-primary" :disabled="busy">{{busy?'正在处理…':'查询已记录事件'}}</button></div></form>
<section v-if="windowData" ref="eventsPanel" class="panel"><div class="panel-heading"><div><h3>来源事件 · {{windowData.items.length}} / {{windowData.total}}</h3><p>最多纳入200条，{{windowData.truncated?'本次已截断，超出部分未知':'本次未达到条数上限'}}。没有事件不证明通道未使用或没有风险。</p></div></div><p v-if="!windowData.items.length" class="message">当前范围没有携带数据上下文的事件。请先接入对应来源，或核对来源和时间范围。</p><div v-else class="table-wrap"><table><thead><tr><th>观察 / 来源</th><th>通道与操作</th><th>主体 / 设备引用</th><th>对象与去向</th><th>来源结果 / 检查</th></tr></thead><tbody><tr v-for="e in windowData.items" :key="e.id"><td>{{formatDate(e.observedAt)}}<small>{{e.source}} · #{{e.id}}</small><small>{{e.sourceCurrent?'来源当前有效':'历史来源已失效'}}</small></td><td>{{dataChannelLabels[e.dataContext.channel]||e.dataContext.channel}}<small>{{e.dataContext.operation}} · {{e.rule}}</small></td><td><code>{{e.dataContext.subjectRef?.slice(0,12)||'未记录主体'}}<small>{{e.dataContext.deviceRef?.slice(0,12)||'未记录设备'}}</small></code></td><td><code>{{e.dataContext.fileDigest?.slice(0,16)||e.dataContext.objectRef?.slice(0,16)||'未记录对象'}}</code><small>{{e.dataContext.destinationDomain||'未记录目的地域名'}}</small><small>{{e.dataContext.categories.join('、')||'未取得内容类别'}}</small></td><td>{{dataEnforcementLabels[e.dataContext.enforcement]}}<template v-if="e.dataContext.endpoint"><small>{{dataEndpointScopeLabels[e.dataContext.endpoint.scope]||e.dataContext.endpoint.scope}} · {{dataEndpointStageLabels[e.dataContext.endpoint.stage]||e.dataContext.endpoint.stage}}</small><small v-if="e.dataContext.endpoint.policyId">策略 #{{e.dataContext.endpoint.policyId}} · v{{e.dataContext.endpoint.policyRevision}}</small><small v-if="e.dataContext.endpoint.scope==='observation'">观察变化不等于预先阻断</small></template><small>{{e.dataContext.capture==='complete'?'来源声明投影完整':'投影不完整，未观察部分未知'}}</small><a v-if="e.checkId" class="table-link" :href="scenarioContextHref(workspace.slug,'checks/'+e.checkId)">关联检查 #{{e.checkId}}</a><small v-else>活动审计，不创建风险检查</small></td></tr></tbody></table></div></section>
<form v-if="editor" class="panel case-form" @submit.prevent="freeze"><h3>冻结调查证据</h3><p>采用上方当前筛选条件重新读取事件，保存来源、原始编号、关联关系和截断情况；后续反馈不会改写快照。</p><label>调查名称<input v-model="title" required maxlength="120" :disabled="busy" placeholder="例如：指定来源的敏感文件外发调查"></label><button class="button button-primary" :disabled="busy||!title.trim()">生成调查快照</button></form>
<section class="panel"><div class="panel-heading"><div><h3>已冻结调查 · {{cases.length}}</h3><p>每份调查的采用范围以其保存快照为准。</p></div><button class="button" :disabled="busy" @click="load">刷新</button></div><p v-if="!cases.length" class="message">尚无调查快照。先选择真实来源与窗口，再冻结可核对的事件。</p><ul v-else class="case-list"><li v-for="c in cases" :key="c.id"><button class="button" :disabled="busy" @click="choose(c.id)">{{c.title}} · #{{c.id}}</button><span>{{formatDate(c.createdAt)}} · {{c.actor}}</span></li></ul></section>
<section v-if="selected" class="panel case-detail"><div class="panel-heading"><div><h3>{{selected.title}} · #{{selected.id}}</h3><p>{{formatDate(selected.scope.from)}} 至 {{formatDate(selected.scope.to)}}</p></div><div class="actions"><button class="button" :disabled="busy" @click="exportCase('html')">导出调查 HTML</button><button class="button" :disabled="busy" @click="exportCase('json')">导出调查 JSON</button></div></div><div class="case-body"><h4>同来源事件关联</h4><article v-for="(chain,index) in selected.snapshot.chains" :key="index"><strong>关联证据组 {{index+1}} · 来源 #{{chain.sourceId}}</strong><p>{{chain.summary}}</p><p>{{chain.channels.map(c=>dataChannelLabels[c]||c).join('、')}} · 事件 {{chain.eventIds.map(id=>'#'+id).join('、')}}</p></article><h4>覆盖与未知条件</h4><ul><li v-for="v in selected.snapshot.coverage" :key="v">{{v}}</li></ul><small>冻结摘要 {{selected.snapshotDigest}}</small>
<form v-if="editor && selected.notes.length<200" class="case-form" @submit.prevent="addFeedback"><h4>人工研判反馈</h4><label>反馈类别<select v-model="feedback" :disabled="busy"><option value="needs_investigation">继续调查</option><option value="expected_activity">符合已核对业务预期</option><option value="false_positive">已核对为误报</option></select></label><label>核对依据<textarea v-model="note" required maxlength="600" rows="3" :disabled="busy"></textarea></label><button class="button" :disabled="busy||!note.trim()">保存反馈</button></form>
<p v-if="editor && aiMode!=='hybrid'">当前引擎仅使用本地能力。可先在分类分级的“识别引擎与 AI”配置中明确启用混合模式，再选择运营参考模型。</p><form v-if="editor && aiMode==='hybrid' && selected.notes.length<200" class="case-form" @submit.prevent="assess"><h4>可选 AI 运营参考</h4><p>仅发送下方预览的事件类别、规则、执行声明与链编号，不发送主体/设备引用、文件摘要、路径、SQL或提示词。模型结论不自动处置或关闭检查。</p><details><summary>查看将发送的事件投影</summary><pre>{{JSON.stringify(dataCaseAIPreview(selected),null,2)}}</pre></details><label>选择运营参考模型<select v-model.number="profileId" :disabled="busy"><option :value="0">请选择已启用且允许元数据的模型</option><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}} · {{p.model}}</option></select></label><label class="consent"><input v-model="consent" type="checkbox" :disabled="busy||!profileId">允许向所选模型发送预览投影，用于本次参考研判（可能产生费用）</label><button class="button" :disabled="busy||!consent||!profileId||selected.snapshot.window.items.length>100">生成运营参考</button><p v-if="selected.snapshot.window.items.length>100">模型参考最多采用100条事件，请缩小范围后生成新快照。</p></form>
<p v-if="selected.notes.length>=200">这份调查已达到反馈与参考记录预算。请保留导出，在后续调查中继续记录，原证据保持留存。</p><h4>反馈与模型参考记录</h4><p v-if="!selected.notes.length">尚无反馈或模型参考。</p><article v-for="n in selected.notes" :key="n.id"><strong>{{n.kind==='feedback'?'人工反馈':'AI 参考 · 未自动采用'}}</strong><p>{{feedbackText(n.snapshot)}}</p><small>{{n.actor}} · {{formatDate(n.createdAt)}}</small><details><summary>核对完整保存记录</summary><pre>{{JSON.stringify(n.snapshot,null,2)}}</pre></details></article></div></section></section></template>
<style scoped>
.data-security-panel{display:grid;gap:20px;min-width:0}.data-security-panel h2{font-size:18px}.data-security-panel h3{font-size:15px}.data-security-panel h4{font-size:13px}.data-security-panel p,.data-security-panel li{font-size:12px;line-height:1.85;color:var(--secondary)}.source-guide,.data-filter,.case-form{padding:18px 20px}.data-filter{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.data-filter label,.case-form label{display:grid;gap:7px;font-size:12px}.data-security-panel input,.data-security-panel select,.data-security-panel textarea{font:inherit;color:var(--ink);background:var(--surface);padding:10px;border:1px solid var(--input-line);border-radius:6px;min-width:0}.data-filter .actions{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap}.data-security-panel table{width:100%;min-width:800px;border-collapse:collapse}.data-security-panel td,.data-security-panel th{text-align:left;padding:13px;font-size:12px;border-bottom:1px solid var(--line);vertical-align:top}.data-security-panel small{display:block;color:var(--secondary);font-size:11px;margin-top:5px;overflow-wrap:anywhere}.data-security-panel code{font-size:11px;overflow-wrap:anywhere}.data-security-panel summary{cursor:pointer;color:var(--accent);font-size:12px}.case-form{display:grid;gap:14px}.case-form .button{justify-self:start}.case-list{list-style:none;margin:0;padding:18px 20px}.case-list li{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:10px}.case-body{padding:18px 20px}.case-body article{padding:16px 0;border-bottom:1px solid var(--line)}.case-body strong{font-size:12px}.case-body pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}.case-form .consent{display:flex;align-items:flex-start;gap:10px}.consent input{margin-top:3px}@media(max-width:800px){.data-filter{grid-template-columns:1fr}}
</style>
